function clean(value) {
  return String(value ?? "").trim();
}

function toNumber(value) {
  const n = Number(String(value ?? "").replace(",", "."));
  return Number.isNaN(n) ? 0 : n;
}

function normalizeDate(value) {
  const v = clean(value);
  if (!v) return "";

  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v;

  if (/^\d{2}\/\d{2}\/\d{4}$/.test(v)) {
    const [d, m, y] = v.split("/");
    return `${y}-${m}-${d}`;
  }

  return v;
}

function parseListaFechas(value) {
  const v = clean(value);
  if (!v) return [];

  return v
    .split(/[,;\n]/)
    .map(x => normalizeDate(x))
    .filter(Boolean);
}

return items.map(item => {
  const d = item.json;

  return {
    json: {
      tipo_item: "medico_disponibilidad",

      periodo: clean(d["Periodo"]),
      clave_disponibilidad: clean(d["Clave disponibilidad"]),

      medico_id: clean(d.medico_id),
      nombre_medico: clean(d.nombre_medico),
      email_medico: clean(d.email_medico || d.remitente_mail).toLowerCase(),

      no_puedo: parseListaFechas(d.no_puedo),
      preferiria_librar: parseListaFechas(d.preferiria_librar),
      prefiere_guardia: parseListaFechas(d.prefiere_guardia),
      dobletes: parseListaFechas(d.dobletes),

      rotacion: clean(d.rotacion),
      rotacion_externa: clean(d.rotacion_externa).toLowerCase(),
      restricciones: clean(d.restricciones),
      anio_residencia: clean(d.anio_residencia),
      objetivo_guardias: toNumber(d.objetivo_guardias),
      observaciones: clean(d.observaciones),

      origen_extraccion: clean(d.origen_extraccion),
      num_correos_agrupados: toNumber(d.num_correos_agrupados),
      messageIds: clean(d.messageIds),
      fecha_ultimo_correo: clean(d.fecha_ultimo_correo),
    }
  };
});

function pad(n) {
  return String(n).padStart(2, "0");
}

function parseBool(value) {
  if (typeof value === "boolean") return value;
  const v = String(value || "").toLowerCase().trim();
  return v === "true" || v === "verdadero" || v === "sí" || v === "si";
}

function toISODate(date) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function addDays(date, days) {
  const d = new Date(date.getTime());
  d.setDate(d.getDate() + days);
  return d;
}

const salida = [];

for (const item of items) {
  const limpio = {};

  for (const [key, value] of Object.entries(item.json)) {
    limpio[String(key).trim()] = value;
  }

  const fechaRaw = String(limpio.Fecha || limpio.fecha || "").trim();

  if (!fechaRaw) continue;

  let fechaInicio;

  // Formato tipo 1/6/2026
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(fechaRaw)) {
    const [dia, mes, anio] = fechaRaw.split("/").map(Number);
    fechaInicio = new Date(anio, mes - 1, dia);
  }
  // Formato tipo 2026-06-01
  else if (/^\d{4}-\d{2}-\d{2}$/.test(fechaRaw)) {
    const [anio, mes, dia] = fechaRaw.split("-").map(Number);
    fechaInicio = new Date(anio, mes - 1, dia);
  } else {
    continue;
  }

  const semana = limpio.Semana || limpio.semana;
  const numGuardias = Number(limpio.Num_guardias ?? limpio.num_guardias ?? 1);
  const dobleResidente = parseBool(limpio.Doble_residente ?? limpio.doble_residente);

  // Expandimos la semana completa: lunes a domingo
  for (let i = 0; i < 7; i++) {
    const fechaDia = addDays(fechaInicio, i);
    const iso = toISODate(fechaDia);

    // Nos quedamos solo con junio 2026
    if (!iso.startsWith("2026-06-")) continue;

    salida.push({
      json: {
        tipo_item: "guardia_necesaria",
        semana,
        fecha: iso,
        num_guardias: numGuardias,
        doble_residente: dobleResidente
      }
    });
  }
}

return salida;

function clean(value) {
  return String(value ?? "").trim();
}

function toNumber(value) {
  const n = Number(String(value ?? "").replace(",", "."));
  return Number.isNaN(n) ? 0 : n;
}

function boolLike(value) {
  if (typeof value === "boolean") return value;
  const v = clean(value).toLowerCase();
  return v === "true" || v === "verdadero" || v === "sí" || v === "si";
}

function includesDate(lista, fecha) {
  return Array.isArray(lista) && lista.includes(fecha);
}

function getDiaSemana(fecha) {
  const d = new Date(`${fecha}T00:00:00`);
  const dias = ["domingo", "lunes", "martes", "miércoles", "jueves", "viernes", "sábado"];
  return dias[d.getDay()];
}

function esFinDeSemana(fecha) {
  const d = new Date(`${fecha}T00:00:00`);
  const day = d.getDay();
  return day === 0 || day === 6;
}

// Cambia estos nombres si tus nodos se llaman distinto
const guardias = $items("Code limpiar guardias").map(item => item.json);
const medicos = $items("Code limpiar disponibilidades").map(item => item.json);

const guardiasValidas = guardias
  .filter(g => clean(g.fecha) !== "")
  .filter(g => toNumber(g.num_guardias) > 0)
  .sort((a, b) => clean(a.fecha).localeCompare(clean(b.fecha)));

const medicosValidos = medicos
  .filter(m => clean(m.medico_id) !== "" || clean(m.email_medico) !== "");

// 1. Lista única de médicos, sin repetir toda la disponibilidad en cada guardia
const medicosCompactos = medicosValidos.map(m => ({
  medico_id: clean(m.medico_id),
  nombre_medico: clean(m.nombre_medico),
  email_medico: clean(m.email_medico),
  anio_residencia: clean(m.anio_residencia),
  rotacion: clean(m.rotacion),
  rotacion_externa: clean(m.rotacion_externa),
  objetivo_guardias: toNumber(m.objetivo_guardias),
  restricciones: clean(m.restricciones),
  observaciones: clean(m.observaciones),
  no_puedo: m.no_puedo || [],
  preferiria_librar: m.preferiria_librar || [],
  prefiere_guardia: m.prefiere_guardia || [],
  dobletes: m.dobletes || []
}));

// 2. Guardias compactas: candidatos solo con id + variables del día
const guardiasPreparadas = [];

for (const g of guardiasValidas) {
  const fecha = clean(g.fecha);

  const candidatos = [];

  for (const m of medicosValidos) {
    if (includesDate(m.no_puedo, fecha)) {
      continue;
    }

    const prefeririaLibrar = includesDate(m.preferiria_librar, fecha);
    const prefiereGuardia = includesDate(m.prefiere_guardia, fecha);
    const aceptaDoblete = includesDate(m.dobletes, fecha);

    let score = 100;

    if (prefeririaLibrar) score -= 25;
    if (prefiereGuardia) score += 20;

    if (boolLike(g.doble_residente) && clean(m.anio_residencia) === "R4") {
      score += 5;
    }

    candidatos.push({
      medico_id: clean(m.medico_id),
      score_dia: score,
      preferiria_librar: prefeririaLibrar,
      prefiere_guardia: prefiereGuardia,
      acepta_doblete: aceptaDoblete
    });
  }

  candidatos.sort((a, b) => b.score_dia - a.score_dia);

  guardiasPreparadas.push({
    guardia_id: `${fecha}_${clean(g.semana).replace(/\s+/g, "_")}`,
    fecha,
    semana: clean(g.semana),
    dia_semana: getDiaSemana(fecha),
    es_fin_de_semana: esFinDeSemana(fecha),
    num_guardias: toNumber(g.num_guardias),
    doble_residente: boolLike(g.doble_residente),
    candidatos
  });
}

const totalPuestosGuardia = guardiasPreparadas.reduce(
  (acc, g) => acc + toNumber(g.num_guardias),
  0
);

return [
  {
    json: {
      periodo: "junio_2026",
      total_dias_guardia: guardiasPreparadas.length,
      total_puestos_guardia: totalPuestosGuardia,
      total_medicos: medicosCompactos.length,
      medicos: medicosCompactos,
      guardias: guardiasPreparadas
    }
  }
];

// Resolver CSP — Backtracking + Forward Checking + MRV + Branch & Bound
//
// CATÁLOGO DE REGLAS DURAS (HARD CONSTRAINTS):
//   HARD R1: Médico debe estar en candidatos de la guardia.
//   HARD R2: Médico no puede tener esa fecha en su lista no_puedo.
//   HARD R3: No repetir médico dentro de la misma guardia (alldifferent).
//   HARD R4: Días consecutivos prohibidos (distancia = 1) para el mismo médico.
//   HARD R5: Distancia = 2 prohibida salvo doblete pre-acordado.
//   HARD R7: En guardias doble_residente, no 2× R2.
//   HARD R8: R2 no puede ocupar guardias de 1 sola persona (num_guardias === 1).
//
// REGLAS BLANDAS:
//   SOFT R6: objetivo_guardias NO es tope absoluto.
//
// VERSIÓN MÁS EFECTIVA OBSERVADA:
//   - Beam Search activo.
//   - Beam width = 5.
//   - LCV fuerte con margen de score = 35.
//   - MRV + Degree heuristic.
//   - Forward Checking.
//   - Branch & Bound.
//   - Hueco solo si no hay candidatos viables.

const TIME_LIMIT_MS = 30000;
const HUECO_PENALTY = -5000;

const BONUS_BAJO_OBJETIVO = 25;
const BONUS_PRIMERA_GUARDIA = 25;

const PENALTY_PREFERIRIA_LIBRAR = -80;
const PENALTY_FLEX_SOBRECARGA = -15;

const PENALTY_SOBRE_OBJETIVO = -80;
const PENALTY_SOBRE_OBJETIVO_EXTRA = -40;

// ---------- Parámetros experimentales ----------
const USE_BEAM_SEARCH = true;
const BEAM_WIDTH = 5;
const SCORE_TIE_MARGIN_FOR_LCV = 35;
const TIMEOUT_CHECK_MASK = 0x1FF;

const startTime = Date.now();
const deadline = startTime + TIME_LIMIT_MS;

const data = items[0].json;
const periodo = data.periodo;
const medicos = Array.isArray(data.medicos) ? data.medicos : [];
const guardiasInput = Array.isArray(data.guardias) ? data.guardias : [];

if (medicos.length === 0) throw new Error("input.medicos está vacío");
if (guardiasInput.length === 0) throw new Error("input.guardias está vacío");

const parseDate = f => new Date(`${f}T00:00:00.000Z`);
const absDiff = (a, b) => Math.abs(Math.round((parseDate(b) - parseDate(a)) / 86400000));

const medicosById = new Map(medicos.map(m => [String(m.medico_id), m]));
const guardiasOrd = [...guardiasInput].sort((a, b) => parseDate(a.fecha) - parseDate(b.fecha));
const guardiaByFecha = new Map(guardiasOrd.map(g => [g.fecha, g]));

const anioOf = id => String(medicosById.get(String(id))?.anio_residencia || "");

// ---------- Cálculo del objetivo implícito para los flex ----------
const totalPuestos = guardiasOrd.reduce((acc, g) => acc + (Number(g.num_guardias) || 0), 0);

const sumaObjetivosExplicitos = medicos.reduce((acc, m) => {
  const o = Number(m.objetivo_guardias) || 0;
  return o > 0 ? acc + o : acc;
}, 0);

const numFlex = medicos.filter(m => (Number(m.objetivo_guardias) || 0) === 0).length;
const restoParaFlex = Math.max(0, totalPuestos - sumaObjetivosExplicitos);
const objetivoImplicito = numFlex > 0 ? restoParaFlex / numFlex : 0;

function objetivoEfectivo(medico) {
  const explicit = Number(medico?.objetivo_guardias) || 0;
  if (explicit > 0) return explicit;
  return objetivoImplicito;
}

// ---------- Construcción de variables y dominios iniciales ----------
const variables = [];

for (const g of guardiasOrd) {
  const num = Number(g.num_guardias) || 0;

  for (let slot = 0; slot < num; slot++) {
    let dom = (g.candidatos || [])
      .map(c => String(c.medico_id))
      .filter(id => medicosById.has(id))
      .filter(id => !((medicosById.get(id).no_puedo || []).map(String).includes(g.fecha)));

    if (num === 1) {
      dom = dom.filter(id => anioOf(id) !== "R2");
    }

    variables.push({
      key: `${g.guardia_id}__${slot}`,
      guardia: g,
      slot,
      domainOriginal: dom,
      currentDomain: new Set(dom)
    });
  }
}

function getCandidato(guardia, medicoId) {
  return (guardia.candidatos || []).find(c => String(c.medico_id) === String(medicoId));
}

function aceptaDobleteEntreFechas(medico, fechaA, fechaB) {
  const set = new Set((medico.dobletes || []).map(String));
  if (set.has(fechaA) && set.has(fechaB)) return true;

  const gA = guardiaByFecha.get(fechaA);
  const gB = guardiaByFecha.get(fechaB);
  const cA = gA ? getCandidato(gA, medico.medico_id) : null;
  const cB = gB ? getCandidato(gB, medico.medico_id) : null;

  return cA?.acepta_doblete === true && cB?.acepta_doblete === true;
}

function softScore(v, medicoId, contadorActual) {
  const id = String(medicoId);
  const candidato = getCandidato(v.guardia, id);
  const medico = medicosById.get(id);
  const asignadas = contadorActual.get(id) || 0;
  const explicit = Number(medico?.objetivo_guardias) || 0;
  const efTarget = objetivoEfectivo(medico);

  let s = Number(candidato?.score_dia) || 0;

  if (candidato?.prefiere_guardia === true) s += 15;
  if (candidato?.preferiria_librar === true) s += PENALTY_PREFERIRIA_LIBRAR;

  if (asignadas === 0) {
    s += BONUS_PRIMERA_GUARDIA;
  }

  if (asignadas < efTarget) {
    s += BONUS_BAJO_OBJETIVO;
  }

  if (efTarget > 0 && asignadas >= efTarget) {
    const exceso = (asignadas - Math.floor(efTarget)) + 1;

    if (explicit > 0) {
      s += PENALTY_SOBRE_OBJETIVO;
      s += PENALTY_SOBRE_OBJETIVO_EXTRA * Math.max(0, exceso - 1);
    } else {
      s += PENALTY_FLEX_SOBRECARGA * Math.max(1, exceso);
    }
  }

  return s;
}

function newState() {
  const fechasPorMedico = new Map();
  const contadorPorMedico = new Map();

  for (const m of medicos) {
    fechasPorMedico.set(String(m.medico_id), []);
    contadorPorMedico.set(String(m.medico_id), 0);
  }

  return { assigned: new Map(), fechasPorMedico, contadorPorMedico };
}

// ---------- Forward checking ----------
function forwardCheck(state, v, medicoId, unassigned) {
  const id = String(medicoId);
  const fecha = v.guardia.fecha;
  const medico = medicosById.get(id);
  const removed = [];

  for (const v2 of unassigned) {
    if (!v2.currentDomain.has(id)) continue;

    let drop = false;

    if (v2.guardia.guardia_id === v.guardia.guardia_id) {
      drop = true;
    } else {
      const d = absDiff(fecha, v2.guardia.fecha);

      if (d === 1) drop = true;
      else if (d === 2 && !aceptaDobleteEntreFechas(medico, fecha, v2.guardia.fecha)) {
        drop = true;
      }
    }

    if (drop) {
      v2.currentDomain.delete(id);
      removed.push(v2);
    }
  }

  return { id, removed };
}

function undoForwardCheck(undo) {
  for (const v2 of undo.removed) v2.currentDomain.add(undo.id);
}

// ---------- LCV ----------
function futureImpact(state, v, medicoId, unassigned) {
  const id = String(medicoId);
  const fecha = v.guardia.fecha;
  const medico = medicosById.get(id);
  let impact = 0;

  for (const v2 of unassigned) {
    if (!v2.currentDomain.has(id)) continue;

    let drop = false;

    if (v2.guardia.guardia_id === v.guardia.guardia_id) {
      drop = true;
    } else {
      const d = absDiff(fecha, v2.guardia.fecha);

      if (d === 1) drop = true;
      else if (d === 2 && !aceptaDobleteEntreFechas(medico, fecha, v2.guardia.fecha)) {
        drop = true;
      }
    }

    if (drop) impact++;
  }

  return impact;
}

function upperBound(unassigned, state) {
  let bound = 0;

  for (const v of unassigned) {
    let bestS = HUECO_PENALTY;

    for (const id of v.currentDomain) {
      const s = softScore(v, id, state.contadorPorMedico);
      if (s > bestS) bestS = s;
    }

    bound += bestS;
  }

  return bound;
}

// ---------- HARD R7: no 2× R2 ----------
function noDosR2PromisingForGuardia(guardia, state) {
  if (!guardia.doble_residente) return true;

  const ids = [];

  for (let s = 0; s < guardia.num_guardias; s++) {
    const id = state.assigned.get(`${guardia.guardia_id}__${s}`);
    if (id !== undefined && id !== null) ids.push(id);
  }

  const numR2 = ids.map(id => anioOf(id)).filter(a => a === "R2").length;
  return numR2 < 2;
}

function checkNoDosR2Final(guardia, state) {
  if (!guardia.doble_residente) return true;

  const ids = [];

  for (let s = 0; s < guardia.num_guardias; s++) {
    const id = state.assigned.get(`${guardia.guardia_id}__${s}`);
    if (id) ids.push(id);
  }

  const numR2 = ids.map(id => anioOf(id)).filter(a => a === "R2").length;
  return numR2 < 2;
}

function wouldViolateNoDosR2(v, medicoId, state) {
  if (!v.guardia.doble_residente) return false;
  if (anioOf(medicoId) !== "R2") return false;

  for (let s = 0; s < v.guardia.num_guardias; s++) {
    if (s === v.slot) continue;

    const aid = state.assigned.get(`${v.guardia.guardia_id}__${s}`);
    if (aid && anioOf(aid) === "R2") {
      return true;
    }
  }

  return false;
}

function solucionCompleta(state) {
  for (const g of guardiasOrd) {
    if (!checkNoDosR2Final(g, state)) return false;
  }

  return true;
}

// ---------- MRV + degree heuristic ----------
function pickMRV(unassigned) {
  let bestVar = null;
  let bestSize = Infinity;
  let bestDegree = -Infinity;

  for (const v of unassigned) {
    const sz = v.currentDomain.size;

    let degree = 0;

    for (const v2 of unassigned) {
      if (v2 === v) continue;

      if (v2.guardia.guardia_id === v.guardia.guardia_id) {
        degree += 3;
      } else {
        const d = absDiff(v.guardia.fecha, v2.guardia.fecha);
        if (d === 1) degree += 2;
        else if (d === 2) degree += 1;
      }
    }

    if (sz < bestSize || (sz === bestSize && degree > bestDegree)) {
      bestSize = sz;
      bestDegree = degree;
      bestVar = v;
      if (sz === 0) return bestVar;
    }
  }

  return bestVar;
}

function compareCandidates(a, b, state) {
  const diffScore = b.score - a.score;

  if (Math.abs(diffScore) > SCORE_TIE_MARGIN_FOR_LCV) {
    return diffScore;
  }

  if (a.impact !== b.impact) {
    return a.impact - b.impact;
  }

  if (b.score !== a.score) return b.score - a.score;

  const cargaA = state.contadorPorMedico.get(a.id) || 0;
  const cargaB = state.contadorPorMedico.get(b.id) || 0;
  if (cargaA !== cargaB) return cargaA - cargaB;

  const medicoA = medicosById.get(a.id);
  const medicoB = medicosById.get(b.id);
  const targetA = objetivoEfectivo(medicoA);
  const targetB = objetivoEfectivo(medicoB);
  const deficitA = targetA - cargaA;
  const deficitB = targetB - cargaB;

  return deficitB - deficitA;
}

const best = { score: -Infinity, solution: null, iterations: 0, hitTimeout: false };

// ---------- Fallback inicial ----------
(function fallbackTodoHuecos() {
  const state = newState();

  for (const v of variables) {
    state.assigned.set(v.key, null);
  }

  if (solucionCompleta(state)) {
    best.score = variables.length * HUECO_PENALTY;
    best.solution = new Map(state.assigned);
  }
})();

// ---------- Greedy baseline ----------
(function greedyBaseline() {
  const state = newState();
  let score = 0;

  for (const v of variables) {
    const candidatosValidos = [];

    for (const id of v.domainOriginal) {
      const m = medicosById.get(id);

      let dup = false;

      for (let s = 0; s < v.guardia.num_guardias; s++) {
        if (s === v.slot) continue;

        if (state.assigned.get(`${v.guardia.guardia_id}__${s}`) === id) {
          dup = true;
          break;
        }
      }

      if (dup) continue;

      const fechas = state.fechasPorMedico.get(id) || [];
      let bad = false;

      for (const f of fechas) {
        const d = absDiff(f, v.guardia.fecha);

        if (d === 1) {
          bad = true;
          break;
        }

        if (d === 2 && !aceptaDobleteEntreFechas(m, f, v.guardia.fecha)) {
          bad = true;
          break;
        }
      }

      if (bad) continue;
      if (wouldViolateNoDosR2(v, id, state)) continue;

      candidatosValidos.push({
        id,
        score: softScore(v, id, state.contadorPorMedico),
        impact: 0
      });
    }

    candidatosValidos.sort((a, b) => compareCandidates(a, b, state));

    const elegido = candidatosValidos[0];

    if (elegido) {
      state.assigned.set(v.key, elegido.id);
      state.fechasPorMedico.get(elegido.id).push(v.guardia.fecha);
      state.contadorPorMedico.set(
        elegido.id,
        (state.contadorPorMedico.get(elegido.id) || 0) + 1
      );
      score += elegido.score;
    } else {
      state.assigned.set(v.key, null);
      score += HUECO_PENALTY;
    }
  }

  if (solucionCompleta(state) && score > best.score) {
    best.score = score;
    best.solution = new Map(state.assigned);
  }
})();

// ---------- Backtracking ----------
function solve(unassigned, state, currentScore) {
  best.iterations++;

  if ((best.iterations & TIMEOUT_CHECK_MASK) === 0 && Date.now() > deadline) {
    best.hitTimeout = true;
    return;
  }

  if (unassigned.size === 0) {
    if (!solucionCompleta(state)) return;

    if (currentScore > best.score) {
      best.score = currentScore;
      best.solution = new Map(state.assigned);
    }

    return;
  }

  const ub = currentScore + upperBound(unassigned, state);
  if (ub <= best.score) return;

  const v = pickMRV(unassigned);
  unassigned.delete(v);

  let candidates = [...v.currentDomain]
    .filter(id => !wouldViolateNoDosR2(v, id, state))
    .map(id => ({
      id,
      score: softScore(v, id, state.contadorPorMedico),
      impact: futureImpact(state, v, id, unassigned)
    }))
    .sort((a, b) => compareCandidates(a, b, state));

  const totalCandidates = candidates.length;

  if (USE_BEAM_SEARCH && candidates.length > BEAM_WIDTH) {
    candidates = candidates.slice(0, BEAM_WIDTH);
  }

  for (const { id, score } of candidates) {
    state.assigned.set(v.key, id);
    state.fechasPorMedico.get(id).push(v.guardia.fecha);

    const prev = state.contadorPorMedico.get(id) || 0;
    state.contadorPorMedico.set(id, prev + 1);

    const promising = noDosR2PromisingForGuardia(v.guardia, state);

    if (promising) {
      const undo = forwardCheck(state, v, id, unassigned);
      solve(unassigned, state, currentScore + score);
      undoForwardCheck(undo);
    }

    state.assigned.delete(v.key);

    const arr = state.fechasPorMedico.get(id);
    arr.splice(arr.lastIndexOf(v.guardia.fecha), 1);

    state.contadorPorMedico.set(id, prev);

    if (best.hitTimeout) {
      unassigned.add(v);
      return;
    }
  }

  if (totalCandidates === 0) {
    state.assigned.set(v.key, null);

    if (noDosR2PromisingForGuardia(v.guardia, state)) {
      solve(unassigned, state, currentScore + HUECO_PENALTY);
    }

    state.assigned.delete(v.key);
  }

  unassigned.add(v);
}

const unassigned = new Set(variables);
solve(unassigned, newState(), 0);

if (!best.solution) {
  throw new Error("No se encontró ninguna solución que cumpla las restricciones duras.");
