// Validador final — verificación defensiva sobre la salida del solver.
// Recorre el calendario y comprueba que no haya violaciones de restricciones duras.
// Lo normal es que no encuentre nada (el solver ya las cumple por construcción),
// pero deja constancia explícita para depuración y auditoría.
//
// IMPORTANTE:
// objetivo_guardias NO es un tope duro.
// Si un médico supera su objetivo, se registra como advertencia soft, no como violación hard.
//
// HARD R7 ACTUALIZADA:
// En guardias doble_residente, solo está prohibido tener 2 o más R2.
// Un R2 puede ir con R3 o con R4. Eso NO es violación.

const data = items[0].json;
const input = data.input_original;
const calendario = data.calendario;

const parseDate = f => new Date(`${f}T00:00:00.000Z`);
const absDiff = (a, b) => Math.abs(Math.round((parseDate(b) - parseDate(a)) / 86400000));

const medicosById = new Map((input.medicos || []).map(m => [String(m.medico_id), m]));
const guardiasById = new Map((input.guardias || []).map(g => [String(g.guardia_id), g]));

function getCandidato(guardia, medicoId) {
  return (guardia.candidatos || []).find(c => String(c.medico_id) === String(medicoId));
}

function aceptaDobleteEntreFechas(medico, fechaA, fechaB) {
  const set = new Set((medico.dobletes || []).map(String));
  if (set.has(fechaA) && set.has(fechaB)) return true;

  const gA = (input.guardias || []).find(g => g.fecha === fechaA);
  const gB = (input.guardias || []).find(g => g.fecha === fechaB);
  const cA = gA ? getCandidato(gA, medico.medico_id) : null;
  const cB = gB ? getCandidato(gB, medico.medico_id) : null;

  return cA?.acepta_doblete === true && cB?.acepta_doblete === true;
}

const violaciones_hard = [];
const advertencias_soft = [];

const fechasPorMedico = new Map();

for (const a of (calendario.asignaciones || [])) {
  const guardia = guardiasById.get(String(a.guardia_id));

  if (!guardia) {
    violaciones_hard.push({
      tipo: "GUARDIA_NO_EXISTE",
      guardia_id: a.guardia_id
    });
    continue;
  }

  const ids = (a.medico_ids || []).map(String);
  const puestosEsperados = Number(guardia.num_guardias) || 0;

  // Cobertura exacta: si hay menos médicos que puestos, es advertencia soft
  // porque el solver permite huecos para garantizar salida válida.
  if (ids.length !== puestosEsperados) {
    advertencias_soft.push({
      tipo: "COBERTURA_NO_EXACTA",
      guardia_id: a.guardia_id,
      fecha: guardia.fecha,
      esperadas: puestosEsperados,
      asignadas: ids.length,
      huecos: Math.max(0, puestosEsperados - ids.length),
      exceso: Math.max(0, ids.length - puestosEsperados)
    });
  }

  if (new Set(ids).size !== ids.length) {
    violaciones_hard.push({
      tipo: "MEDICO_REPETIDO_EN_GUARDIA",
      guardia_id: a.guardia_id,
      fecha: guardia.fecha
    });
  }

  for (const id of ids) {
    const medico = medicosById.get(id);

    if (!medico) {
      violaciones_hard.push({
        tipo: "MEDICO_NO_EXISTE",
        guardia_id: a.guardia_id,
        medico_id: id
      });
      continue;
    }

    if (!getCandidato(guardia, id)) {
      violaciones_hard.push({
        tipo: "MEDICO_FUERA_DE_CANDIDATOS",
        guardia_id: a.guardia_id,
        fecha: guardia.fecha,
        medico_id: id
      });
    }

    if ((medico.no_puedo || []).map(String).includes(guardia.fecha)) {
      violaciones_hard.push({
        tipo: "MEDICO_EN_NO_PUEDO",
        guardia_id: a.guardia_id,
        fecha: guardia.fecha,
        medico_id: id
      });
    }

    if (!fechasPorMedico.has(id)) fechasPorMedico.set(id, []);
    fechasPorMedico.get(id).push(guardia.fecha);
  }

  // HARD R7: en guardias doble_residente, solo se prohíbe 2× R2.
  // Un R2 con R3 o R4 está permitido.
  if (guardia.doble_residente && ids.length >= 2) {
    const anios = ids.map(id => String(medicosById.get(id)?.anio_residencia || ""));
    const numR2 = anios.filter(a => a === "R2").length;

    if (numR2 >= 2) {
      violaciones_hard.push({
        tipo: "DOBLE_R2_EN_DOBLE_RESIDENTE",
        guardia_id: a.guardia_id,
        fecha: guardia.fecha,
        medico_ids: ids,
        anios
      });
    }
  }
}

for (const [id, fechasOrig] of fechasPorMedico.entries()) {
  const medico = medicosById.get(id);
  const fechas = [...fechasOrig].sort();

  for (let i = 0; i < fechas.length - 1; i++) {
    const d = absDiff(fechas[i], fechas[i + 1]);

    if (d === 1) {
      violaciones_hard.push({
        tipo: "DIAS_CONSECUTIVOS",
        medico_id: id,
        nombre_medico: medico?.nombre_medico || "",
        fechas: [fechas[i], fechas[i + 1]]
      });
    }

    if (d === 2 && !aceptaDobleteEntreFechas(medico || {}, fechas[i], fechas[i + 1])) {
      violaciones_hard.push({
        tipo: "DOBLETE_NO_PERMITIDO",
        medico_id: id,
        nombre_medico: medico?.nombre_medico || "",
        fechas: [fechas[i], fechas[i + 1]]
      });
    }
  }

  const obj = Number(medico?.objetivo_guardias) || 0;

  if (obj > 0 && fechas.length > obj) {
    advertencias_soft.push({
      tipo: "MEDICO_SOBRE_OBJETIVO",
      medico_id: id,
      nombre_medico: medico?.nombre_medico || "",
      objetivo: obj,
      asignadas: fechas.length,
      exceso: fechas.length - obj
    });
  }
}

for (const m of (input.medicos || [])) {
  const id = String(m.medico_id);
  const fechas = fechasPorMedico.get(id) || [];
  const obj = Number(m.objetivo_guardias) || 0;

  if (obj > 0 && fechas.length < obj) {
    advertencias_soft.push({
      tipo: "MEDICO_BAJO_OBJETIVO",
      medico_id: id,
      nombre_medico: m.nombre_medico,
      objetivo: obj,
      asignadas: fechas.length,
      deficit: obj - fechas.length
    });
  }

  for (const fechaPref of (m.preferiria_librar || [])) {
    if (fechas.includes(fechaPref)) {
      advertencias_soft.push({
        tipo: "ASIGNADO_EN_PREFERIRIA_LIBRAR",
        medico_id: id,
        nombre_medico: m.nombre_medico,
        fecha: fechaPref
      });
    }
  }
}

return [{
  json: {
    ...data,
    validacion: {
      valido_hard: violaciones_hard.length === 0,
      total_violaciones_hard: violaciones_hard.length,
      total_advertencias_soft: advertencias_soft.length,
      violaciones_hard,
      advertencias_soft
    }
  }
}];

