function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash = hash | 0;
  }
  return Math.abs(hash).toString(16).slice(0, 8);
}

const now = new Date();
const pad = n => String(n).padStart(2, '0');

const yyyy = now.getFullYear();
const mm = pad(now.getMonth() + 1);
const dd = pad(now.getDate());
const hh = pad(now.getHours());
const min = pad(now.getMinutes());

const periodo = sol.periodo || 'periodo';
const stamp = `${yyyy}-${mm}-${dd}_${hh}${min}`;

const stableString = JSON.stringify({
  periodo: sol.periodo,
  calendario: sol.calendario,
  resumen_medicos: sol.resumen_medicos,
  validacion: sol.validacion,
});

const solutionHash = simpleHash(stableString);

const safePeriodo = String(periodo)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-zA-Z0-9_ -]/g, '')
  .replace(/\s+/g, '_')
  .slice(0, 40);

const sheetName = `${safePeriodo}_${stamp}_${solutionHash}`.slice(0, 90);
const solutionId = `sol_${safePeriodo}_${stamp}_${solutionHash}`;

const medicos = sol.input_original?.medicos || [];
const guardias = sol.input_original?.guardias || [];
const asignaciones = sol.calendario?.asignaciones || [];
const resumenMedicos = sol.resumen_medicos || [];
const validacion = sol.validacion || {};

const medicoById = Object.fromEntries(
  medicos.map(m => [String(m.medico_id), m])
);

const guardiaByFecha = Object.fromEntries(
  guardias.map(g => [g.fecha, g])
);

function nombreMedico(id) {
  return medicoById[String(id)]?.nombre_medico || String(id);
}

function row(c1 = '', c2 = '', c3 = '', c4 = '', c5 = '', c6 = '', c7 = '', c8 = '') {
  return {
    sheet_name: sheetName,
    solution_id: solutionId,
    col_1: c1,
    col_2: c2,
    col_3: c3,
    col_4: c4,
    col_5: c5,
    col_6: c6,
    col_7: c7,
    col_8: c8,
  };
}

const rows = [];

rows.push(row('SOLUCIÓN GUARDIAS'));
rows.push(row('solution_id', solutionId));
rows.push(row('sheet_name', sheetName));
rows.push(row('created_at', now.toISOString()));
rows.push(row('periodo', periodo));
rows.push(row('solution_hash', solutionHash));
rows.push(row());

rows.push(row('RESUMEN GENERAL'));
rows.push(row('puestos cubiertos', `${sol.total_puestos_cubiertos ?? 0}/${sol.total_puestos_necesarios ?? 0}`));
rows.push(row('huecos', sol.total_huecos ?? 0));
rows.push(row('válido hard', validacion.valido_hard ?? sol.valido_hard ?? ''));
rows.push(row('violaciones hard', validacion.total_violaciones_hard ?? sol.total_violaciones_hard ?? 0));
rows.push(row('advertencias soft', validacion.total_advertencias_soft ?? sol.total_advertencias_soft ?? 0));
rows.push(row('score total', sol.score_total ?? ''));
rows.push(row());

rows.push(row('VIOLACIONES HARD'));
rows.push(row('tipo', 'médico', 'fecha', 'detalle'));

const violacionesHard = validacion.violaciones_hard || [];
if (violacionesHard.length === 0) {
  rows.push(row('Sin violaciones hard'));
} else {
  for (const v of violacionesHard) {
    rows.push(row(
      v.tipo || '',
      v.nombre_medico || v.medico_id || '',
      v.fecha || '',
      v.detalle || JSON.stringify(v)
    ));
  }
}
rows.push(row());

rows.push(row('ADVERTENCIAS SOFT'));
rows.push(row('tipo', 'médico', 'objetivo', 'asignadas', 'diferencia'));

const advertencias = validacion.advertencias_soft || [];
if (advertencias.length === 0) {
  rows.push(row('Sin advertencias soft'));
} else {
  for (const a of advertencias) {
    const diferencia =
      a.exceso !== undefined ? `+${a.exceso}` :
      a.deficit !== undefined ? `-${a.deficit}` :
      '';

    rows.push(row(
      a.tipo || '',
      a.nombre_medico || a.medico_id || '',
      a.objetivo ?? '',
      a.asignadas ?? '',
      diferencia
    ));
  }
}
rows.push(row());

rows.push(row('RESUMEN POR MÉDICO'));
rows.push(row('médico', 'año', 'objetivo', 'asignadas', 'diferencia', 'fechas'));

for (const m of resumenMedicos) {
  rows.push(row(
    m.nombre_medico || '',
    m.anio_residencia || '',
    m.objetivo_efectivo ?? m.objetivo_explicito ?? '',
    m.num_guardias_asignadas ?? '',
    m.diferencia_vs_objetivo ?? '',
    Array.isArray(m.fechas_asignadas) ? m.fechas_asignadas.join(', ') : ''
  ));
}
rows.push(row());

rows.push(row('CALENDARIO'));
rows.push(row('fecha', 'día', 'médicos asignados', 'nº guardias', 'doble residente', 'semana'));

for (const a of asignaciones) {
  const g = guardiaByFecha[a.fecha] || {};
  const nombres = (a.medico_ids || []).map(nombreMedico).join(', ');

  rows.push(row(
    a.fecha || '',
    g.dia_semana || '',
    nombres,
    g.num_guardias ?? (a.medico_ids || []).length,
    g.doble_residente ? 'Sí' : 'No',
    g.semana || ''
  ));
}
rows.push(row());


return rows.map(r => ({ json: r }));
